 static Dictionary<string,object>D(object o){return o as Dictionary<string,object>??new Dictionary<string,object>();}static object V(Dictionary<string,object>d,string k){return d.ContainsKey(k)?d[k]:null;}static string S(Dictionary<string,object>d,string k){return Convert.ToString(V(d,k));}static IEnumerable<Dictionary<string,object>>A(object o){if(o is IEnumerable&&!(o is string)&&!(o is IDictionary))foreach(var x in (IEnumerable)o)yield return D(x);}static Dictionary<string,object>Parse(string s){return new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Deserialize<Dictionary<string,object>>(s);}static Dictionary<string,object>Read(string p){if(new FileInfo(p).Length>8388608)throw new InvalidDataException("Quality evidence exceeds8MiB");return Parse(File.ReadAllText(p,Encoding.UTF8));}
 public static string Describe(string root){try{var w=Read(Path.Combine(root,"analysis-readiness.json"));string payload=S(w,"payload_json");if(ProvenanceAudit.Sha(payload)!=S(w,"payload_sha256"))throw new InvalidDataException("Readiness report hash mismatch");var r=Parse(payload);string id=S(r,"case_id");if(S(r,"schema")!="reveng-analysis-readiness-v1"||id!="qualified-comparison-001"||S(r,"status")!="USEFUL_ANALYSIS_NOT_PROVEN"||!Object.Equals(V(r,"auto_admission"),false)||!Object.Equals(V(r,"execution_authorization"),false)||!Object.Equals(V(r,"new_inference_permitted"),false))throw new InvalidDataException("Readiness policy mismatch");var names=new[]{"attribution-cases/"+id+"-input.json","attribution-cases/"+id+"-catalog.json","attribution-cases/"+id+"-output.json","attribution-cases/"+id+"-response.json","analysis-quality/"+id+"-semantic-review.json","analysis-quality/"+id+"-receipt.json","analysis-quality/"+id+"-completion.json"};var files=D(V(r,"files"));if(files.Count!=names.Length)throw new InvalidDataException("Readiness evidence inventory mismatch");foreach(string name in names)if(!files.ContainsKey(name)||!LocalResearchController.Hash(Path.Combine(root,name)).Equals(S(files,name),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Quality evidence changed: "+name);var catalog=Read(Path.Combine(root,names[1]));var output=Read(Path.Combine(root,names[2]));ProvenanceAudit.ValidateBindings(catalog,output,Read(Path.Combine(root,names[0])),Read(Path.Combine(root,names[3])));var receipt=Read(Path.Combine(root,names[5]));var completion=Read(Path.Combine(root,names[6]));var manual=Read(Path.Combine(root,names[4]));var recorded=D(V(completion,"request_response_hashes"));foreach(var pair in new[]{new[]{names[0],"sealed-request.json"},new[]{names[2],"extraction.json"},new[]{names[3],"response.json"}})if(!LocalResearchController.Hash(Path.Combine(root,pair[0])).Equals(S(recorded,pair[1]),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Case differs from historical runtime capture");if(S(receipt,"model_calls")!="1"||S(completion,"finish_reason")!="stop"||!Object.Equals(V(manual,"automatic_admission"),false)||!Object.Equals(V(manual,"stage2_authorized"),false))throw new InvalidDataException("Historical receipt/manual review policy mismatch");var fields=ProvenanceAudit.Audit(id,catalog,output);if(fields.Count!=3||fields.Any(f=>!f.SourceHashValid||!f.ReferenceValid))throw new InvalidDataException("Source field bindings not valid");var b=new StringBuilder("ПОЛЕЗНОСТЬ AI-АНАЛИЗА НЕ ДОКАЗАНА\r\n");b.AppendLine("Подготовленный вход в очереди не означает качественный анализ, разрешённый запуск или одобрение идеи.").AppendLine("Сейчас доступны сохранённые свидетельства, поиск, ручные гипотезы и их экспорт.").AppendLine().AppendLine("ПОСЛЕДНИЙ СОХРАНЁННЫЙ ТЕСТ — исторический, новый запуск не выполнялся").AppendLine("Кейс: "+id).AppendLine("Один запрос: "+S(D(V(receipt,"usage")),"prompt_tokens")+" входных и "+S(D(V(receipt,"usage")),"completion_tokens")+" выходных токенов; "+Convert.ToDouble(V(receipt,"wall_seconds")).ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+" с; GPU "+S(receipt,"GPU_layers")+"; finish_reason=stop, без обрезания.").AppendLine("Точные input/catalog и response/output, а также все семь файлов доказательств проверены по хешам.").AppendLine().AppendLine("Буквальная диагностика воспроизведения текста (не AI-проверка смысла):");b.AppendLine("Проверка цепочки: raw response.content → JSON extraction без подстановки исходника; полный пакет трёх полей сохранён. 1142 входных +1026 выходных токенов при контексте32768; завершение stop. Скрытое усечение этого запуска не обнаружено.");b.AppendLine("Пробел контракта: summary maxLength=1000 разрешал полную копию каждого поля (235/231/991). Структурная проверка не проверяла полезное сжатие. Краткость была мягкой инструкцией рядом с сохранением всех условий; влияние sampler по одному запуску не установлено.");b.AppendLine("Следующий тест только подготовлен: те же3 реальных поля, короткая суть отдельно от условий/вопросов, summary до120/120/420 символов; ручная проверка каждого существенного ограничения и границ авторов. Длина и валидный JSON не доказывают сохранение смысла. Новый запрос не квалифицирован, не одобрен и не выполнен.");int exact=0,near=0;foreach(var sp in D(V(catalog,"sources"))){var source=D(sp.Value);foreach(var fp in D(V(source,"fields"))){var row=D(fp.Value);string original=row.ContainsKey("text")?S(row,"text"):S(row,"full_text");string summary=S(D(V(D(V(D(V(output,"sources")),sp.Key)),fp.Key)),"summary_as_attributed_message");bool e=original==summary,n=original.Replace('’','\'')==summary.Replace('’','\'');if(e)exact++;if(n)near++;b.AppendLine(sp.Key+" / "+fp.Key+": источник "+ProvenanceAudit.Count(original)+", summary "+ProvenanceAudit.Count(summary)+" символов; "+(e?"точная полная копия":n?"полное воспроизведение с заменой апострофов":"не дословно; это само по себе не доказывает полезный анализ"));}}b.AppendLine().AppendLine("Ручной разбор ассистентом: на этих трёх полях прежнее смешение авторов отсутствует и существенные ограничения сохранены. Это узкий результат, не общая квалификация модели.").AppendLine("Сжатие: отсутствует — "+exact+" дословных копии, "+near+" из 3 полных воспроизведений после учёта апострофов. По одному запуску с несколькими изменениями настроек причину установить нельзя.").AppendLine("Формат и буквальные ссылки не равны смысловой полезности; оплата, покупатели и спрос не установлены.").AppendLine("AUTO_ADMISSION=false; STOP не снимается; повтор/stage2 не разрешены.").AppendLine("Новый эксперимент требует отдельного согласования. Исполнитель, модель или сервис этой кнопкой не запускаются.");return b.ToString();}catch(Exception ex){return "ДИАГНОСТИКА КАЧЕСТВА НЕДОСТУПНА: "+ex.Message+". Это не подтверждение готовности; AUTO_ADMISSION=false. Сохранённые источники и ручные черновики остаются доступны. AI/сеть не запускались.";}}
